mapper.select:
select s.id, s.season_id as seasonId, se.season_name as seasonName, s.stage_id as stageId, st.stage_name as stageName, s.team_id as teamId, t.team_name as teamName, s.player_id as playerId, p.player_no as playerNo, ifnull(nullif(p.game_nickname, ''), mp.nickname) as displayName, af.access_url as avatarUrl, p.position_code as positionCode, s.games, s.starts, s.minutes_seconds as minutesSeconds, s.points, s.rebounds, s.assists, s.steals, s.blocks, s.turnovers, s.fouls, s.avg_minutes as avgMinutes, s.avg_points as avgPoints, s.avg_rebounds as avgRebounds, s.avg_assists as avgAssists, s.avg_steals as avgSteals, s.avg_blocks as avgBlocks, s.field_goal_pct as fieldGoalPct, s.three_point_pct as threePointPct, s.free_throw_pct as freeThrowPct, s.avg_efficiency as avgEfficiency, s.double_double_count as doubleDoubleCount, s.triple_double_count as tripleDoubleCount, s.last_calculated_time as lastCalculatedTime from basket_player_season_stat s left join basket_tournament_season se on se.id = s.season_id and se.is_delete = 0 left join basket_tournament_stage st on st.id = s.stage_id and st.is_delete = 0 left join basket_team t on t.id = s.team_id and t.is_delete = 0 left join basket_player_profile p on p.id = s.player_id and p.is_delete = 0 left join basket_member_profile mp on mp.member_id = p.member_id and mp.is_delete = 0 left join basket_file_asset af on af.id = mp.avatar_file_id and af.is_delete = 0 where s.is_delete = 0 and s.season_id = #{seasonId} and s.stage_id = #{stageId} and s.team_id = #{teamId} and s.player_id = #{playerId}
and (p.game_nickname like concat('%', #{keyword}, '%') or mp.nickname like concat('%', #{keyword}, '%') or p.player_no like concat('%', #{keyword}, '%'))
order by s.avg_points desc, s.player_id

mapper.delete:
delete from basket_player_season_stat
where season_id = #{seasonId}
and stage_id = #{stageId}
